//! `cargo xtask gen-compose`: writes `docker-compose.yml` (local) and
//! `docker-compose.dokploy.yml` (production) for the gateway and all 168
//! nano services, plus the frontend in production. The files are committed
//! but never edited by hand.

use std::fmt::Write as _;
use std::path::Path;

use domain::SlotId;

use crate::option;

const HEADER: &str = "\
# GENERATED by `cargo xtask gen-compose` — DO NOT EDIT BY HAND.
# Change backend/xtask/src/compose.rs and regenerate instead.
";

/// Host port of an exposed slot in the local compose: 9000 + slot index.
const EXPOSED_SLOT_BASE_PORT: usize = 9000;

pub fn run(backend_dir: &Path, options: &[String]) -> anyhow::Result<()> {
    let domain = option(options, "--domain")?.unwrap_or("izbi.beer");
    let exposed = match option(options, "--expose-slots")? {
        Some(list) => list
            .split(',')
            .map(|slot| slot.trim().parse::<SlotId>())
            .collect::<Result<Vec<_>, _>>()?,
        None => Vec::new(),
    };

    let local = backend_dir.join("docker-compose.yml");
    std::fs::write(&local, local_compose(&exposed))?;
    println!("wrote {}", local.display());

    let dokploy = backend_dir.join("docker-compose.dokploy.yml");
    std::fs::write(&dokploy, dokploy_compose(domain))?;
    println!("wrote {}", dokploy.display());
    Ok(())
}

/// Local stack: images are built from source, only the gateway (and the
/// slots passed with `--expose-slots`) get host ports.
fn local_compose(exposed: &[SlotId]) -> String {
    let mut out = String::from(HEADER);
    out.push_str(
        "#
# Local stack: gateway + 168 nano services built from source.
#   cargo xtask gen-keys && docker compose up --build
# Only the gateway is published (localhost:8080). Regenerate with
# `--expose-slots pn-09,sr-10` to publish slots on port 9000 + slot index.

name: meet

x-nano-env: &nano-env
  JWT_PUBLIC_KEYS: ${JWT_PUBLIC_KEYS:?run `cargo xtask gen-keys` first}
  ALLOWED_ORIGIN: ${ALLOWED_ORIGIN:-http://localhost:*}
  LOG_FORMAT: pretty

x-nano: &nano
  image: meet-nano:local
  # Built once by nano-pn-00 and reused by the other 167 services.
  pull_policy: never
  restart: unless-stopped

services:
  gateway:
    image: meet-gateway:local
    build:
      context: .
      dockerfile: docker/gateway.Dockerfile
    restart: unless-stopped
    environment:
      JWT_KEY_ID: ${JWT_KEY_ID:-k1}
      JWT_PRIVATE_KEY: ${JWT_PRIVATE_KEY:?run `cargo xtask gen-keys` first}
      ALLOWED_ORIGIN: ${ALLOWED_ORIGIN:-http://localhost:*}
      LOG_FORMAT: pretty
    ports:
      - \"8080:8080\"
    volumes:
      - gateway-data:/data
",
    );

    for slot in SlotId::all() {
        let _ = write!(
            out,
            "
  nano-{slot}:
    <<: *nano
",
        );
        if slot.index() == 0 {
            out.push_str(
                "    build:
      context: .
      dockerfile: docker/nano.Dockerfile
    pull_policy: build
",
            );
        }
        let _ = write!(
            out,
            "    environment:
      <<: *nano-env
      SLOT_ID: {slot}
    volumes:
      - nano-{slot}:/data
"
        );
        if exposed.contains(&slot) {
            let port = EXPOSED_SLOT_BASE_PORT + slot.index();
            let _ = write!(out, "    ports:\n      - \"{port}:8080\"\n");
        }
    }

    out.push_str(&volumes());
    out
}

/// Production stack for Dokploy: prebuilt images, every service behind
/// Traefik on its own first-level subdomain of `domain` (`meet`, `api-meet`,
/// `{slot}-meet`), all of them on `dokploy-network`.
fn dokploy_compose(domain: &str) -> String {
    let mut out = String::from(HEADER);
    let _ = write!(
        out,
        "#
# Production stack for Dokploy behind its Traefik.
# Required variables (Dokploy → Environment): FRONTEND_IMAGE, GATEWAY_IMAGE,
# NANO_IMAGE, JWT_PRIVATE_KEY, JWT_PUBLIC_KEYS. Optional: JWT_KEY_ID,
# ALLOWED_ORIGIN, TOKEN_TTL_DAYS, TRAEFIK_ENTRYPOINT.
#
# Traffic is proxied by Cloudflare. Routers only enable TLS; Traefik serves
# the Cloudflare Origin CA certificate for *.{domain} added once in Dokploy
# (ADR 0006). No ACME, so no certificate rate limits.

x-nano-env: &nano-env
  JWT_PUBLIC_KEYS: ${{JWT_PUBLIC_KEYS:?}}
  ALLOWED_ORIGIN: ${{ALLOWED_ORIGIN:-https://meet.{domain}}}

x-nano: &nano
  image: ${{NANO_IMAGE:?}}
  # Images are tagged `latest`; without this a redeploy keeps the copy already on the host.
  pull_policy: always
  restart: unless-stopped
  networks:
    - dokploy-network
  healthcheck:
    test: [\"CMD\", \"/nano\", \"healthcheck\"]
    interval: 30s
    timeout: 3s
    start_period: 5s
    retries: 3

services:
  frontend:
    image: ${{FRONTEND_IMAGE:?}}
    pull_policy: always
    restart: unless-stopped
    environment:
      NUXT_PUBLIC_API_MODE: production
      NUXT_PUBLIC_GATEWAY_BASE: https://api-meet.{domain}
      NUXT_PUBLIC_SLOT_BASE_TEMPLATE: https://{{slot}}-meet.{domain}
    networks:
      - dokploy-network
    labels:
      - traefik.enable=true
      - traefik.http.routers.meet-web.rule=Host(`meet.{domain}`)
      - traefik.http.routers.meet-web.entrypoints=${{TRAEFIK_ENTRYPOINT:-websecure}}
      - traefik.http.routers.meet-web.tls=true
      - traefik.http.services.meet-web.loadbalancer.server.port=3000

  gateway:
    image: ${{GATEWAY_IMAGE:?}}
    pull_policy: always
    restart: unless-stopped
    environment:
      JWT_KEY_ID: ${{JWT_KEY_ID:-k1}}
      JWT_PRIVATE_KEY: ${{JWT_PRIVATE_KEY:?}}
      ALLOWED_ORIGIN: ${{ALLOWED_ORIGIN:-https://meet.{domain}}}
      TOKEN_TTL_DAYS: ${{TOKEN_TTL_DAYS:-14}}
    volumes:
      - gateway-data:/data
    networks:
      - dokploy-network
    healthcheck:
      test: [\"CMD\", \"/gateway\", \"healthcheck\"]
      interval: 30s
      timeout: 3s
      start_period: 5s
      retries: 3
    labels:
      - traefik.enable=true
      - traefik.http.routers.meet-api.rule=Host(`api-meet.{domain}`)
      - traefik.http.routers.meet-api.entrypoints=${{TRAEFIK_ENTRYPOINT:-websecure}}
      - traefik.http.routers.meet-api.tls=true
      - traefik.http.services.meet-api.loadbalancer.server.port=8080
"
    );

    for slot in SlotId::all() {
        let _ = write!(
            out,
            "
  nano-{slot}:
    <<: *nano
    environment:
      <<: *nano-env
      SLOT_ID: {slot}
    volumes:
      - nano-{slot}:/data
    labels:
      - traefik.enable=true
      - traefik.http.routers.meet-{slot}.rule=Host(`{slot}-meet.{domain}`)
      - traefik.http.routers.meet-{slot}.entrypoints=${{TRAEFIK_ENTRYPOINT:-websecure}}
      - traefik.http.routers.meet-{slot}.tls=true
      - traefik.http.services.meet-{slot}.loadbalancer.server.port=8080
"
        );
    }

    out.push_str(
        "
networks:
  dokploy-network:
    external: true
",
    );
    out.push_str(&volumes());
    out
}

fn volumes() -> String {
    let mut out = String::from("\nvolumes:\n  gateway-data:\n");
    for slot in SlotId::all() {
        let _ = writeln!(out, "  nano-{slot}:");
    }
    out
}
